package com.binary;

public class swap2Numbers {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		        int a = 5, b = 7;
		        a = a^b;
		        b = b^a;
		        a = a^b;
		        System.out.println("After swapping: a = " + a + ", b = " + b);
		        
		}

}